/**
 * WSA Multi-Channel Publisher - Enterprise SVG Icons Library
 * High-definition, clean, crisp SVG icons with scalable viewports (Zero external CDN/font dependencies)
 */

declare(strict_types=1);

if (!defined('APP_SECURE')) {
    http_response_code(403);
    exit('Direct access not allowed.');
}

class Icons
{
    /**
     * Render an enterprise SVG icon
     */
    public static function svg(string $name, int $size = 18, string $className = 'icon-svg'): string
    {
        $icons = self::getLibrary();
        $svgInner = $icons[$name] ?? self::defaultIcon();

        return sprintf(
            '<svg class="%s" width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">%s</svg>',
            htmlspecialchars($className, ENT_QUOTES, 'UTF-8'),
            $size,
            $size,
            $svgInner
        );
    }

    /**
     * Render platform specific brand SVG icon
     */
    public static function platform(string $platform, int $size = 20, string $className = 'icon-platform'): string
    {
        $brands = self::getBrandLibrary();
        $svg = $brands[$platform] ?? self::getLibrary()['globe'];

        return sprintf(
            '<svg class="%s" width="%d" height="%d" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">%s</svg>',
            htmlspecialchars($className, ENT_QUOTES, 'UTF-8'),
            $size,
            $size,
            $svg
        );
    }

    private static function defaultIcon(): string
    {
        return '<circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>';
    }

